export const LOCAL_ENV_FILENAME = '.env';
export const GLOBAL_CONFIG_DIR = '.config/frai';
export const GLOBAL_CONFIG_FILE = 'config';
export * from './constants.js';
export * from './paths.js';
export * from './key-store.js';
import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const sanitizeValue = (value) => {
  if (!value) return null;
  return value.trim().replace(/^['"]|['"]$/g, '');
};

export const hasLocalApiKey = (cwd = process.cwd()) => fs.existsSync(resolveLocalEnvPath(cwd));

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const content = fs.readFileSync(envPath, 'utf8');
  const match = content.match(/^\s*OPENAI_API_KEY\s*=\s*(.+)\s*$/m);
  return match ? sanitizeValue(match[1]) : null;
};

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  if (!key) throw new Error('API key is required');
  const envPath = resolveLocalEnvPath(cwd);
  const content = `OPENAI_API_KEY=${key}\n`;
  fs.writeFileSync(envPath, content, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  fs.existsSync(resolveGlobalConfigPath(homeDir));

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  const content = fs.readFileSync(configPath, 'utf8');
  try {
    const parsed = JSON.parse(content);
    return sanitizeValue(parsed.OPENAI_API_KEY);
  } catch (error) {
    return null;
  }
};

export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  if (!key) throw new Error('API key is required');
  const configDir = resolveGlobalConfigDir(homeDir);
  ensureDir(configDir);
  const configPath = resolveGlobalConfigPath(homeDir);
  const payload = JSON.stringify({ OPENAI_API_KEY: key }, null, 2);
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};
import fs from 'fs';
import os from 'os';
import path from 'path';
import { describe, expect, it, beforeEach, afterEach } from 'vitest';

import {
  getGlobalApiKey,
  getLocalApiKey,
  hasGlobalApiKey,
  hasLocalApiKey,
  setGlobalApiKey,
  setLocalApiKey
} from './key-store.js';
import { resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

describe('config key store', () => {
  let tmpCwd;
  let tmpHome;

  beforeEach(() => {
    tmpCwd = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-cwd-'));
    tmpHome = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-home-'));
  });

  afterEach(() => {
    fs.rmSync(tmpCwd, { recursive: true, force: true });
    fs.rmSync(tmpHome, { recursive: true, force: true });
  });

  it('handles local env api key lifecycle', () => {
    expect(hasLocalApiKey(tmpCwd)).toBe(false);
    expect(getLocalApiKey(tmpCwd)).toBeNull();

    setLocalApiKey('test-key', tmpCwd);

    expect(hasLocalApiKey(tmpCwd)).toBe(true);
    expect(getLocalApiKey(tmpCwd)).toBe('test-key');

    const envPath = resolveLocalEnvPath(tmpCwd);
    const content = fs.readFileSync(envPath, 'utf8');
    expect(content).toContain('OPENAI_API_KEY=test-key');
  });

  it('handles global config api key lifecycle', () => {
    expect(hasGlobalApiKey(tmpHome)).toBe(false);
    expect(getGlobalApiKey(tmpHome)).toBeNull();

    setGlobalApiKey('global-key', tmpHome);

    expect(hasGlobalApiKey(tmpHome)).toBe(true);
    expect(getGlobalApiKey(tmpHome)).toBe('global-key');

    const configPath = resolveGlobalConfigPath(tmpHome);
    const content = fs.readFileSync(configPath, 'utf8');
    expect(JSON.parse(content).OPENAI_API_KEY).toBe('global-key');
  });
});
import os from 'os';
import path from 'path';

import { GLOBAL_CONFIG_DIR, GLOBAL_CONFIG_FILE, LOCAL_ENV_FILENAME } from './constants.js';

export const resolveLocalEnvPath = (cwd = process.cwd()) =>
  path.join(cwd, LOCAL_ENV_FILENAME);

export const resolveGlobalConfigDir = (homeDir = os.homedir()) =>
  path.join(homeDir, GLOBAL_CONFIG_DIR);

export const resolveGlobalConfigPath = (homeDir = os.homedir()) =>
  path.join(resolveGlobalConfigDir(homeDir), GLOBAL_CONFIG_FILE);
import path from "node:path";
import process from "node:process";

import { Config } from "frai-core";

export interface ResolveEnvOptions {
  root?: string;
}

export const resolveWorkingDirectory = (root?: string) =>
  root ? path.resolve(process.cwd(), root) : process.cwd();

export const resolveOpenAiApiKey = (options: ResolveEnvOptions = {}) => {
  const cwd = options.root ? path.resolve(process.cwd(), options.root) : process.cwd();
  const existing = process.env.OPENAI_API_KEY?.trim();
  if (existing) {
    return existing;
  }

  const local = Config.getLocalApiKey(cwd);
  if (local) {
    process.env.OPENAI_API_KEY = local;
    return local;
  }

  const global = Config.getGlobalApiKey();
  if (global) {
    process.env.OPENAI_API_KEY = global;
    return global;
  }

  return null;
};

export const requireOpenAiApiKey = (options: ResolveEnvOptions = {}) => {
  const key = resolveOpenAiApiKey(options);
  if (!key) {
    throw new Error(
      "OPENAI_API_KEY is required. Configure it via `frai setup`, `.env`, or environment variables."
    );
  }
  return key;
};
