import fs from 'fs';

import { resolveGlobalConfigDir, resolveGlobalConfigPath, resolveLocalEnvPath } from './paths.js';

const API_KEY_NAME = 'OPENAI_API_KEY';

// Matches `[export ]OPENAI_API_KEY=<rest>`; group 1 is everything up to the value.
const ENV_KEY_LINE = new RegExp(`^(\\s*(?:export\\s+)?${API_KEY_NAME}\\s*=\\s*)(.*)$`);

const ensureDir = (dirPath) => {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true, mode: 0o700 });
  }
};

const normalizeKey = (value) => {
  if (typeof value !== 'string') return null;
  const trimmed = value.trim();
  return trimmed ? trimmed : null;
};

const assertValidKey = (key) => {
  if (!key) throw new Error('API key is required');
  if (/[\r\n]/.test(key)) throw new Error('API key must not contain line breaks');
};

/**
 * Splits a raw `.env` value into the value itself and whatever follows it
 * (closing quote excluded, trailing whitespace/comment included).
 * Returns null when the text after a closing quote is not a comment.
 */
const parseEnvValue = (raw) => {
  const quote = raw[0];
  if (quote === '"' || quote === "'") {
    for (let i = 1; i < raw.length; i += 1) {
      if (quote === '"' && raw[i] === '\\') {
        i += 1;
        continue;
      }
      if (raw[i] === quote) {
        const trailing = raw.slice(i + 1);
        if (!/^\s*(#.*)?$/.test(trailing)) return null;
        const inner = raw.slice(1, i);
        const value = quote === '"' ? inner.replace(/\\(["\\])/g, '$1') : inner;
        return { value, quote, trailing };
      }
    }
  }
  const commentMatch = raw.match(/(^|\s)#/);
  const end = commentMatch ? commentMatch.index : raw.length;
  return { value: raw.slice(0, end).trim(), quote: '', trailing: raw.slice(end).replace(/^\s*$/, '') };
};

const formatEnvValue = (key, preferredQuote) => {
  const needsQuotes = /[\s#"'\\]/.test(key);
  const quote = preferredQuote || (needsQuotes ? '"' : '');
  if (quote === "'" && !key.includes("'")) return `'${key}'`;
  if (quote === '' || quote === "'") {
    return needsQuotes ? `"${key.replace(/(["\\])/g, '\\$1')}"` : key;
  }
  return `"${key.replace(/(["\\])/g, '\\$1')}"`;
};

const splitLines = (content) => content.split('\n');

/** Finds the last active OPENAI_API_KEY definition; the last one wins, as in dotenv. */
const findLastKeyDefinition = (lines) => {
  for (let index = lines.length - 1; index >= 0; index -= 1) {
    const line = lines[index].endsWith('\r') ? lines[index].slice(0, -1) : lines[index];
    const match = line.match(ENV_KEY_LINE);
    if (!match) continue;
    const parsed = parseEnvValue(match[2]);
    if (!parsed) continue;
    return { index, prefix: match[1], hasCarriageReturn: line !== lines[index], ...parsed };
  }
  return null;
};

export const getLocalApiKey = (cwd = process.cwd()) => {
  const envPath = resolveLocalEnvPath(cwd);
  if (!fs.existsSync(envPath)) return null;
  const content = fs.readFileSync(envPath, 'utf8');
  const definition = findLastKeyDefinition(splitLines(content));
  return definition ? normalizeKey(definition.value) : null;
};

export const hasLocalApiKey = (cwd = process.cwd()) => Boolean(getLocalApiKey(cwd));

export const setLocalApiKey = (key, cwd = process.cwd()) => {
  assertValidKey(key);
  const envPath = resolveLocalEnvPath(cwd);
  const content = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
  const lines = splitLines(content);
  const definition = findLastKeyDefinition(lines);

  let next;
  if (definition) {
    const value = formatEnvValue(key, definition.quote);
    const trailing = definition.trailing && !/^\s/.test(definition.trailing) ? ` ${definition.trailing}` : definition.trailing;
    lines[definition.index] = `${definition.prefix}${value}${trailing}${definition.hasCarriageReturn ? '\r' : ''}`;
    next = lines.join('\n');
  } else {
    const eol = content.includes('\r\n') ? '\r\n' : '\n';
    const separator = content && !content.endsWith('\n') ? eol : '';
    next = `${content}${separator}${API_KEY_NAME}=${formatEnvValue(key, '')}${eol}`;
  }

  fs.writeFileSync(envPath, next, { encoding: 'utf8', mode: 0o600 });
  return envPath;
};

const readGlobalConfig = (configPath) => {
  const content = fs.readFileSync(configPath, 'utf8');
  const parsed = JSON.parse(content);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error('expected a JSON object');
  }
  return { parsed, content };
};

export const getGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) => {
  const configPath = resolveGlobalConfigPath(homeDir);
  if (!fs.existsSync(configPath)) return null;
  try {
    return normalizeKey(readGlobalConfig(configPath).parsed[API_KEY_NAME]);
  } catch (error) {
    return null;
  }
};

export const hasGlobalApiKey = (homeDir = process.env.HOME || process.env.USERPROFILE) =>
  Boolean(getGlobalApiKey(homeDir));

export const setGlobalApiKey = (key, homeDir = process.env.HOME || process.env.USERPROFILE) => {
  if (!key) throw new Error('API key is required');
  const configPath = resolveGlobalConfigPath(homeDir);

  let existing = {};
  let trailingNewline = '';
  if (fs.existsSync(configPath)) {
    try {
      const { parsed, content } = readGlobalConfig(configPath);
      existing = parsed;
      trailingNewline = content.endsWith('\n') ? '\n' : '';
    } catch (error) {
      throw new Error(
        `Global config at ${configPath} is not valid JSON (${error.message}); refusing to overwrite it.`
      );
    }
  }

  ensureDir(resolveGlobalConfigDir(homeDir));
  const payload = JSON.stringify({ ...existing, [API_KEY_NAME]: key }, null, 2) + trailingNewline;
  fs.writeFileSync(configPath, payload, { encoding: 'utf8', mode: 0o600 });
  return configPath;
};

