import fs from 'fs';
import os from 'os';
import path from 'path';
import { spawnSync } from 'child_process';
import { it, expect } from 'vitest';

const CLI = path.resolve(__dirname, 'dist/index.js');

it('e2e', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-e2e-'));
  const home = path.join(root, 'home');
  const proj = path.join(root, 'proj');
  const cfgPath = path.join(home, '.config/frai/config');
  fs.mkdirSync(path.dirname(cfgPath), { recursive: true });
  fs.mkdirSync(proj);
  const run = (...args) => {
    const r = spawnSync(process.execPath, [CLI, ...args], {
      cwd: proj,
      env: { ...process.env, HOME: home, OPENAI_API_KEY: '' },
      input: '',
      encoding: 'utf8',
      timeout: 10000
    });
    const out = `$ frai ${args.join(' ')} (exit ${r.status})\n${r.stdout}${r.stderr}`.replace(/\[[^\]]+Z\] /g, '');
    console.log(out);
    return r;
  };
  const env = path.join(proj, '.env');
  const orig = '# top\nFOO=bar\n\nexport OPENAI_API_KEY="sk-old" # rotated\nBAZ=qux';
  fs.writeFileSync(env, orig);
  fs.writeFileSync(cfgPath, '{\n  "theme": "dark",\n  "OPENAI_API_KEY": "old"\n}\n');

  run('config');
  run('setup', '--key', 'sk-new');
  expect(fs.readFileSync(env, 'utf8')).toBe(orig.replace('sk-old', 'sk-new'));
  run('setup', '--key', 'sk-glob', '--global');
  expect(JSON.parse(fs.readFileSync(cfgPath, 'utf8'))).toEqual({ theme: 'dark', OPENAI_API_KEY: 'sk-glob' });
  expect(fs.readFileSync(env, 'utf8')).toBe(orig.replace('sk-old', 'sk-new'));
  run('--setup', '--key', 'sk-leg');
  expect(fs.readFileSync(env, 'utf8')).toBe(orig.replace('sk-old', 'sk-leg'));
  run('--setup', '--key', 'sk-leg2', '--global');
  expect(JSON.parse(fs.readFileSync(cfgPath, 'utf8'))).toEqual({ theme: 'dark', OPENAI_API_KEY: 'sk-leg2' });

  fs.writeFileSync(cfgPath, 'nope');
  const bad = run('setup', '--key', 'x', '--global');
  expect(bad.status).not.toBe(0);
  expect(fs.readFileSync(cfgPath, 'utf8')).toBe('nope');

  fs.rmSync(cfgPath);
  fs.writeFileSync(env, 'OPENAI_API_KEY=\nFOO=1\n');
  run('config');
  fs.rmSync(root, { recursive: true, force: true });
});

